#!/usr/bin/env python3
"""Regenerate the Kodi tables validate.py checks the skin against, from the
Kodi Omega sources (never from memory):

  vendor/kodi/builtins.txt   builtin name + minimum parameter count
                             (xbmc/interfaces/builtins/*Builtins.cpp; a call
                             with fewer parameters is not a command at all -
                             CBuiltins::HasCommand)
  vendor/kodi/actions.txt    action names (xbmc/input/actions/ActionTranslator.cpp)
  vendor/kodi/windowids.txt  window name + id (xbmc/input/WindowTranslator.cpp,
                             xbmc/guilib/WindowIDs.h)
  vendor/kodi/infolabels.txt category.property names Kodi knows, per category
                             (xbmc/GUIInfoManager.cpp, TranslateSingleString)
  windownames.txt            the window names alone (same source)

  KODI_SRC=/path/to/xbmc python3 vendor/kodi/mktables.py   # a local checkout
  python3 vendor/kodi/mktables.py                          # downloads Omega
"""
import os, re, sys, urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(os.path.dirname(HERE))
RAW = "https://raw.githubusercontent.com/xbmc/xbmc/Omega/"
BUILTINS = ["Addon", "Application", "CEC", "GUI", "GUIContainer", "GUIControl", "Library",
            "Optical", "PVR", "Picture", "Player", "Profile", "Skin", "System", "Weather",
            "Android"]


def src(path):
    if os.environ.get("KODI_SRC"):
        return open(os.path.join(os.environ["KODI_SRC"], path), encoding="utf-8").read()
    with urllib.request.urlopen(RAW + path, timeout=60) as r:
        return r.read().decode("utf-8")


def write(path, header, lines):
    with open(path, "w") as f:
        f.write("# " + header + "\n# generated by vendor/kodi/mktables.py from Kodi Omega - do not edit\n")
        f.write("\n".join(lines) + "\n")
    print(f"{os.path.relpath(path, ROOT)}: {len(lines)} entries")


# builtins: {"name", {"description" "more", 1, Function}}
ENTRY = re.compile(r'\{\s*"([a-z][a-z0-9._]*)"\s*,\s*\{\s*(?:"(?:[^"\\]|\\.)*"\s*)+,\s*(\d+)\s*,')
builtins = {}
for b in BUILTINS:
    for name, n in ENTRY.findall(src(f"xbmc/interfaces/builtins/{b}Builtins.cpp")):
        builtins[name] = int(n)
write(os.path.join(HERE, "builtins.txt"), "builtin<TAB>minimum parameters",
      [f"{k}\t{v}" for k, v in sorted(builtins.items())])

# actions: {"left", ACTION_MOVE_LEFT},
at = src("xbmc/input/actions/ActionTranslator.cpp")
body = at[at.index("ActionMappings = {"):]
body = body[:body.index("};")]
actions = sorted(set(re.findall(r'\{\s*"([a-z0-9_.]+)"\s*,\s*ACTION_', body)))
write(os.path.join(HERE, "actions.txt"), "action names (ActionTranslator.cpp)", actions)

# windows: {"home", WINDOW_HOME}, ids from WindowIDs.h
ids = {}
for m in re.finditer(r"^#define\s+(WINDOW_\w+)\s+([(\w +\-)]+?)\s*(?://.*)?$",
                     src("xbmc/guilib/WindowIDs.h"), re.M):
    expr = re.sub(r"WINDOW_\w+", lambda w: str(ids.get(w.group(0), "None")), m.group(2))
    if re.fullmatch(r"[\d()+\- ]+", expr):
        ids[m.group(1)] = eval(expr)          # digits, + - and brackets only
wt = src("xbmc/input/WindowTranslator.cpp")
body = wt[wt.index("WindowMappingByName = {"):]
body = body[:body.index("};")]
wins = re.findall(r'\{\s*"([a-z0-9_]+)"\s*,\s*(WINDOW_\w+)\s*\}', body)
write(os.path.join(HERE, "windowids.txt"), "window name<TAB>id (WindowTranslator.cpp + WindowIDs.h)",
      [f"{n}\t{ids[w]}" for n, w in sorted(wins)])
with open(os.path.join(ROOT, "windownames.txt"), "w") as f:
    f.write("\n".join(sorted(n for n, _ in wins)) + "\n")
print(f"windownames.txt: {len(wins)} names")

# info labels/bools: TranslateSingleString compares cat.name with a literal and
# then either walks an infomap table or compares prop.name with literals. Every
# name met after `cat.name == "x"` (until the next category test) belongs to x.
gi = src("xbmc/GUIInfoManager.cpp")
maps = {}
for m in re.finditer(r"const infomap (\w+)\[\]\s*=\s*\{(.*?)\};", gi, re.S):
    maps[m.group(1)] = set(re.findall(r'\{\s*"([a-z0-9_.]+)"\s*,', m.group(2)))
start = gi.index("int CGUIInfoManager::TranslateSingleString(const std::string &strCondition, bool &listItemDependent)")
end = gi.index("\nint CGUIInfoManager::", start + 10)
# the helpers some categories hand over to, and the tables those walk
helper = {}
for fn in ("TranslateMusicPlayerString", "TranslateVideoPlayerString", "TranslateListItem"):
    i = gi.index(f"\nint CGUIInfoManager::{fn}(")
    j = gi.index("\nint CGUIInfoManager::", i + 10)
    body = gi[i:j]
    helper[fn] = set(re.findall(r'prop\.name\s*==\s*"([a-z0-9_.]+)"', body))
    for arr in re.findall(r"for \(const infomap& \w+ : (\w+)\)", body):
        helper[fn] |= maps.get(arr, set())
cur, known, prev = [], {}, ""
for line in gi[start:end].splitlines():
    if re.search(r"info\.size\(\) == 3", line):
        break                   # three-part names (Container(n).ListItem(m).x...) follow
    cats = re.findall(r'cat\.name\s*==\s*"([a-z0-9_]+)"', line)
    if cats:
        cur = cur + cats if prev.rstrip().endswith("||") else cats
    prev = line
    for c in cur:
        k = known.setdefault(c, set())
        for arr in re.findall(r"for \(const infomap& \w+ : (\w+)\)", line):
            k |= maps.get(arr, set())
        for fn in re.findall(r"(Translate(?:MusicPlayerString|VideoPlayerString|ListItem))\(", line):
            k |= helper[fn]
        k |= set(re.findall(r'(?:prop|info\[1\]|property)\.name\s*==\s*"([a-z0-9_.]+)"', line))
write(os.path.join(HERE, "infolabels.txt"),
      "category.property names from TranslateSingleString (two-part names; parameters not checked)",
      sorted(f"{c}.{p}" for c, ps in known.items() for p in ps))
